namespace SkyrimNpcStudio.Worker.Contracts;

// Universal Body Director (protocol 1.7): read-only body facts of NPCs (body.inspectNpcs) and the packaging of
// a body distribution generated by the studio (export.bodyDistribution). No plugin is written by either.

public sealed record BodyInspectRequest
{
    /// <summary>
    /// Exactly these NPCs ("0A2C8E:Skyrim.esm", "000A2C8E:Skyrim.esm" or a load-order FormID; at most 2000).
    /// Null: every winning NPC_ of the active load order (the population of catalog.searchNpcs), paged by
    /// <see cref="Offset"/> and <see cref="Limit"/>.
    /// </summary>
    public IReadOnlyList<string>? FormKeys { get; init; }

    /// <summary>"female" or "male": only NPCs whose winning record has that sex. Null: both.</summary>
    public string? Sex { get; init; }

    public int Offset { get; init; }

    /// <summary>Page size when <see cref="FormKeys"/> is null; clamped to 1..2000.</summary>
    public int Limit { get; init; } = 500;
}

public sealed record BodyInspectResponse
{
    /// <summary>NPCs matching the request: the whole population when paging, the found ones for explicit FormKeys.</summary>
    public required int Total { get; init; }

    public required IReadOnlyList<BodyNpcInfo> Items { get; init; }

    /// <summary>Requested FormKeys that are not an NPC_ of the active load order (or are not FormKeys at all), as sent.</summary>
    public required IReadOnlyList<string> Missing { get; init; }
}

public sealed record BodyKeywordRef
{
    public required string FormKey { get; init; }
    public string? EditorId { get; init; }
}

public sealed record BodyFactionRef
{
    public required string FormKey { get; init; }
    public string? EditorId { get; init; }
    public required int Rank { get; init; }
}

/// <summary>One ARMA of a skin (ARMO), as the winning record defines it.</summary>
public sealed record BodySkinAddon
{
    public required string FormKey { get; init; }
    public string? EditorId { get; init; }

    /// <summary>The ARMA's primary race (RNAM), or null when it has none.</summary>
    public string? Race { get; init; }

    public required IReadOnlyList<string> AdditionalRaces { get; init; }

    /// <summary>World model path exactly as stored, e.g. "Actors\Character\Character Assets\FemaleBody_1.nif".</summary>
    public string? FemaleModel { get; init; }

    public string? MaleModel { get; init; }

    /// <summary>Biped slots of the addon (30..61).</summary>
    public required IReadOnlyList<int> BodySlots { get; init; }

    /// <summary>
    /// The ARMA's race or additional races include the NPC's effective race or that race's armor race
    /// (the races the game matches an ARMA against).
    /// </summary>
    public required bool AppliesToRace { get; init; }
}

public sealed record BodyHeadPart
{
    public required string FormKey { get; init; }
    public string? EditorId { get; init; }
    public string? PartType { get; init; }
    public string? ModelPath { get; init; }
}

/// <summary>Body facts of one NPC, read from its WINNING record through the load order's link cache.</summary>
public sealed record BodyNpcInfo
{
    public required string FormKey { get; init; }
    public required string FormId { get; init; }
    public string? EditorId { get; init; }
    public string? Name { get; init; }

    /// <summary>"female" or "male", from the record's own configuration flags.</summary>
    public required string Sex { get; init; }

    /// <summary>
    /// The sex the game uses: the one of <see cref="TraitsFrom"/> when the Traits template flag inherits it.
    /// Null when the template chain cannot be resolved statically.
    /// </summary>
    public string? EffectiveSex { get; init; }

    public required string OriginPlugin { get; init; }
    public required string WinningPlugin { get; init; }
    public required bool IsUnique { get; init; }
    public required bool UsesTemplate { get; init; }
    public required IReadOnlyList<string> TemplateFlags { get; init; }
    public RecordRef? Template { get; init; }

    /// <summary>The record's own race (RNAM).</summary>
    public RecordRef? Race { get; init; }

    /// <summary>Flags, keywords and skin of the effective race (the own race when the effective one is unresolved).</summary>
    public required bool IsChild { get; init; }

    public required bool IsPlayable { get; init; }
    public required IReadOnlyList<string> RaceKeywords { get; init; }
    public RecordRef? RaceSkin { get; init; }

    /// <summary>The race the game uses: the own race, or the one of <see cref="TraitsFrom"/> with the Traits template flag.</summary>
    public RecordRef? EffectiveRace { get; init; }

    /// <summary>The skin the game uses (WNAM of <see cref="TraitsFrom"/>, else its race's WNAM).</summary>
    public RecordRef? EffectiveSkin { get; init; }

    /// <summary>FormKey of the NPC_ that actually supplies race and skin (this NPC unless Traits are inherited).</summary>
    public string? TraitsFrom { get; init; }

    /// <summary>The Traits template chain reaches a leveled list, a missing record, a cycle or the depth limit.</summary>
    public required bool TemplateUnresolved { get; init; }

    public required IReadOnlyList<BodyKeywordRef> Keywords { get; init; }
    public RecordRef? Class { get; init; }
    public RecordRef? CombatStyle { get; init; }
    public required IReadOnlyList<BodyFactionRef> Factions { get; init; }

    /// <summary>"npc" (the record's WNAM), "race" (fell back to its race's WNAM) or "none".</summary>
    public required string SkinSource { get; init; }

    /// <summary>The record's own skin: its WNAM, else its race's WNAM.</summary>
    public RecordRef? Skin { get; init; }

    /// <summary>ARMA of <see cref="EffectiveSkin"/> (of <see cref="Skin"/> when the effective one is unresolved).</summary>
    public required IReadOnlyList<BodySkinAddon> SkinAddons { get; init; }

    public required IReadOnlyList<BodyHeadPart> HeadParts { get; init; }
    public required FaceGenPaths FaceGen { get; init; }
    public required IReadOnlyList<string> Notes { get; init; }
}

public sealed record BodyPackageFile
{
    /// <summary>Path inside the mod folder; '/' or '\' separators, relative, no "..".</summary>
    public required string RelativePath { get; init; }

    /// <summary>UTF-8 text, written without BOM.</summary>
    public required string Content { get; init; }
}

public sealed record ExportBodyDistributionRequest
{
    /// <summary>Name of the mod folder (and of the ZIP); a single safe folder name.</summary>
    public required string ModName { get; init; }

    public required string OutputDirectory { get; init; }
    public bool CreateZip { get; init; } = true;
    public string? Author { get; init; }
    public string? Description { get; init; }
    public required IReadOnlyList<BodyPackageFile> Files { get; init; }

    /// <summary>Free key/value pairs copied into manifest.json.</summary>
    public IReadOnlyDictionary<string, string>? Metadata { get; init; }
}

public sealed record ExportBodyDistributionResponse
{
    public required string ModDirectory { get; init; }
    public string? ZipPath { get; init; }
    public required string ManifestPath { get; init; }

    /// <summary>The request's files as written ('/' separators), with size and SHA-256.</summary>
    public required IReadOnlyList<ExportedFile> Files { get; init; }

    public required IReadOnlyList<string> Verification { get; init; }
}
